    @Override // android.app.IntentService, android.app.Service
    public void onDestroy() {
        Log.d("DownloadService", "destroying");
        unregisterReceiver(this.downloadReceiver);
    }

    @Override // android.app.IntentService
    protected void onHandleIntent(Intent intent) {
        Log.d("DownloadService", "service started");
        String url = intent.getStringExtra("url");
        Uri uri = Uri.parse(url);
        Log.d("DownloadService", "Downloading from url: " + url + "file = " + uri.getLastPathSegment());
        DownloadManager.Request request = new DownloadManager.Request(Uri.parse(url));
        request.setDescription("LÖVE Game Download");
        request.setTitle(uri.getLastPathSegment());
        request.setMimeType("application/x-love-game");
        if (Build.VERSION.SDK_INT >= 11) {
            new DownloadRequestSettings_API11();
            DownloadRequestSettings_API11.setup(request);
        }
        request.setDestinationInExternalPublicDir(Environment.DIRECTORY_DOWNLOADS, uri.getLastPathSegment());
        Log.d("DownloadActivity", "creating manager");
        DownloadManager manager = (DownloadManager) getSystemService("download");
        Log.d("DownloadActivity", "enqueuing download");
        manager.enqueue(request);
        Log.d("DownloadActivity", "download receiver = " + this.downloadReceiver);
        IntentFilter intentFilter = new IntentFilter("android.intent.action.DOWNLOAD_COMPLETE");
        registerReceiver(this.downloadReceiver, intentFilter);
    }

    public static boolean isDownloadManagerAvailable(Context context) {
        try {
            if (Build.VERSION.SDK_INT < 9) {
                return false;
            }
            Intent intent = new Intent("android.intent.action.MAIN");
            intent.addCategory("android.intent.category.LAUNCHER");
            intent.setClassName("com.android.providers.downloads.ui", "com.android.providers.downloads.ui.DownloadList");
            List<ResolveInfo> list = context.getPackageManager().queryIntentActivities(intent, 65536);
            return list.size() > 0;
        } catch (Exception e) {
            return false;
        }
    }
}

