    void copyGameToCache(Uri sourceuri) {
        String destinationFilename = getCacheDir().getPath() + "/downloaded.love";
        gamePath = destinationFilename;
        BufferedOutputStream bos = null;
        try {
            BufferedOutputStream bos2 = new BufferedOutputStream(new FileOutputStream(destinationFilename, false));
            bos = bos2;
        } catch (IOException e) {
            Log.d("GameActivity", "Could not open destination file:" + e.getMessage());
        }
        int bytes_written = 0;
        BufferedInputStream bis = null;
        if (sourceuri.getScheme().equals("content")) {
            try {
                bis = new BufferedInputStream(getContentResolver().openInputStream(sourceuri));
            } catch (IOException e2) {
                Log.d("GameActivity", "Could not open game file:" + e2.getMessage());
            }
        } else {
            Log.d("GameActivity", "Unsupported scheme: " + sourceuri.getScheme());
        }
        if (bis != null) {
            try {
                byte[] buf = new byte[1024];
                int chunk_read = bis.read(buf);
                do {
                    bos.write(buf, 0, chunk_read);
                    bytes_written += chunk_read;
                    chunk_read = bis.read(buf);
                } while (chunk_read != -1);
            } catch (IOException e3) {
                Log.d("GameActivity", "Copying failed:" + e3.getMessage());
            }
        }
        if (bis != null) {
            try {
                bis.close();
            } catch (IOException e4) {
                Log.d("GameActivity", "Copying failed: " + e4.getMessage());
            }
        }
        if (bos != null) {
            bos.close();
        }
        Log.d("GameActivity", "Copied " + bytes_written + " bytes");
    }

